"""Second reference: numpy-evaluated, combination-enumerating (no DFS), independent code."""
import itertools, operator
import numpy as np

OPS = {'eq': operator.eq, 'ne': operator.ne, 'lt': operator.lt, 'le': operator.le,
       'gt': operator.gt, 'ge': operator.ge}


def ref2_compile_job(job):
    fields = job['fields']
    names = [f['name'] for f in fields]
    idx = {n: i for i, n in enumerate(names)}
    doms = [list(f['domain']) for f in fields]
    K = job['slots']
    nf = len(fields)
    cells = K * nf
    cell_field = [i for _ in range(K) for i in range(nf)]
    # universe built a completely different way: product over cells, then transposed
    rows = np.array(list(itertools.product(*[doms[cf] for cf in cell_field])), dtype=np.int64)
    U = rows.shape[0]

    def col(ref):
        return rows[:, ref[0] * nf + idx[ref[1]]]

    def tarr(term):
        if 'const' in term:
            return int(term['const'])
        if 'sum' in term:
            cols = [col(r) for r in term['sum']]
            out = np.zeros(U, dtype=np.int64)
            for c in cols:
                out = out + c
            return out
        if 'scale' in term:
            return col(term['ref']) * int(term['scale'])
        return col(term['ref'])

    preds = job['predicates']
    flags = []
    for p in preds:
        if p['kind'] == 'cmp':
            f = OPS[p['op']](tarr(p['left']), tarr(p['right']))
        else:
            fi = idx[p['field']]
            parts = [OPS[p['op']](rows[:, slot * nf + fi], int(p['value'])) for slot in range(K)]
            f = parts[0]
            for q in parts[1:]:
                f = (f | q) if p['kind'] == 'any' else (f & q)
        flags.append(np.asarray(f, dtype=bool))
    train_rows = np.array([list(itertools.chain.from_iterable(w)) for w in job['train']], dtype=np.int64)
    n = train_rows.shape[0]
    tflags = []
    for p in preds:
        if p['kind'] == 'cmp':
            def te(term, M=train_rows):
                if 'const' in term:
                    return int(term['const'])
                if 'sum' in term:
                    out = np.zeros(M.shape[0], dtype=np.int64)
                    for r in term['sum']:
                        out = out + M[:, r[0] * nf + idx[r[1]]]
                    return out
                if 'scale' in term:
                    return M[:, term['ref'][0] * nf + idx[term['ref'][1]]] * int(term['scale'])
                return M[:, term['ref'][0] * nf + idx[term['ref'][1]]]
            f = OPS[p['op']](te(p['left']), te(p['right']))
        else:
            fi = idx[p['field']]
            parts = [OPS[p['op']](train_rows[:, slot * nf + fi], int(p['value'])) for slot in range(K)]
            f = parts[0]
            for q in parts[1:]:
                f = (f | q) if p['kind'] == 'any' else (f & q)
        tflags.append(np.asarray(f, dtype=bool))
    width = job['width']
    P = len(preds)
    rules = []
    for length in range(1, width + 1):
        for comb in itertools.combinations(range(P), length):
            um = np.zeros(U, dtype=bool)
            tm = np.zeros(n, dtype=bool)
            for i in comb:
                um |= flags[i]
                tm |= tflags[i]
            if tm.shape[0] and not tm.all():
                continue
            if um.all():
                continue
            minimal = True
            for i in range(length):
                om = np.zeros(n, dtype=bool)
                for j in comb:
                    if j != comb[i]:
                        om |= tflags[j]
                if om.shape[0] and om.all():
                    minimal = False
                    break
            if not minimal:
                continue
            wit = []
            for i in range(length):
                om = np.zeros(n, dtype=bool)
                for j in comb:
                    if j != comb[i]:
                        om |= tflags[j]
                cand = tflags[comb[i]] & ~om
                wit.append(int(np.argmax(cand)) if cand.any() else None)
            ce = int(np.argmin(um)) if (~um).any() else None
            rules.append({'clause': list(comb), 'witnesses': wit, 'counterexample': ce})
    rules.sort(key=lambda r: (len(r['clause']), r['clause']))
    approved = {tuple(c) for c in job['approved']}
    active = [r['clause'] for r in rules if tuple(r['clause']) in approved]
    answers = []
    for q in job['queries']:
        tpos = q['target'][0] * nf + idx[q['target'][1]]
        good = np.ones(U, dtype=bool)
        for b in q['fixed']:
            good &= rows[:, b['ref'][0] * nf + idx[b['ref'][1]]] == int(b['value'])
        for clause in active:
            um = np.zeros(U, dtype=bool)
            for i in clause:
                um |= flags[i]
            good &= um
        target = rows[:, tpos]
        if q['prefix'] == '':
            ok = np.ones(U, dtype=bool)
        else:
            ok = np.array([str(int(v)).startswith(q['prefix']) for v in np.unique(target)], dtype=bool)
            uniq = np.unique(target)
            sel = ok[np.searchsorted(uniq, target)]
            ok = sel
        good = good & ok
        count = int(good.sum())
        if count:
            wit = int(np.argmax(good))
            vals = np.unique(target[good])
            chars = set()
            end = False
            for v in vals:
                s = str(int(v))
                if s == q['prefix']:
                    end = True
                elif len(s) > len(q['prefix']):
                    chars.add(s[len(q['prefix'])])
            tokens = [d for d in '0123456789' if d in chars] + (['END'] if end else [])
        else:
            wit = None
            tokens = []
        answers.append({'count': count, 'tokens': tokens, 'witness': wit})
    return {'rules': rules, 'active': active, 'answers': answers}
